<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useAuthStore } from "../store/modules/auth";
import { TaskService, type TaskBiz } from "../service/TaskService";
import { TimeUtil } from "../lib/util";
const auth=useAuthStore(), loading=ref(true), unavailable=ref(false);
const counts=ref<(number|null)[]>([null,null,null,null]), todayCounts=ref<(number|null)[]>([null,null,null,null]);
const stats=computed(()=>["全部创作任务","数字人视频","声音合成","语音识别"].map((label,i)=>({label,value:counts.value[i],today:todayCounts.value[i]})));
const tools=[
 {name:"数字人形象",desc:"为内容选择一位专属主角",tag:"AVATAR",path:"/video?tab=videoTemplate",icon:"M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM4 21v-2a8 8 0 0 1 16 0v2"},
 {name:"声音工作室",desc:"让文字拥有鲜活的表达",tag:"VOICE",path:"/sound",icon:"M12 3v18M8 7v10M4 10v4M16 6v12M20 9v6"},
 {name:"素材资源",desc:"收纳每一次创作的灵感",tag:"LIBRARY",path:"/video?tab=videoMaterial",icon:"M3 5h7l2 3h9v12H3zM8 13h8M8 16h5"}];
const steps=[
 {n:"01",name:"准备你的形象",text:"上传清晰的形象视频，或选择云端预设形象。",path:"/video?tab=videoTemplate"},
 {n:"02",name:"连接创作能力",text:"在模型服务中配置文本、声音与数字人模型。",path:"/server"},
 {n:"03",name:"完成第一条视频",text:"回到工作台，串联文案、语音、视频与发布。",path:"/video?tab=ipAgent"}];
const refreshStats=async()=>{loading.value=true;unavailable.value=false;try{if(!window.$mapi){unavailable.value=true;return;}const start=TimeUtil.datetimeToTimestamp(TimeUtil.formatDate(Date.now())+" 00:00:00");const types:(TaskBiz|null)[]=[null,"VideoGen","SoundGenerate","SoundAsr"];const results=await Promise.allSettled(types.map(async type=>Promise.all([TaskService.count(type),TaskService.count(type,start)])));results.forEach((r,i)=>{if(r.status==="fulfilled"){counts.value[i]=r.value[0];todayCounts.value[i]=r.value[1];}else unavailable.value=true;});}catch{unavailable.value=true;}finally{loading.value=false;}};
onMounted(refreshStats);
</script>
