    <div class="voice-composition" aria-hidden="true"><div class="voice-screen"><div class="screen-indicators"><i></i><i></i><i></i><span>IP Bot</span></div><div class="voice-avatar"><svg viewBox="0 0 120 120" fill="none"><circle cx="60" cy="43" r="21"/><path d="M21 108c0-25 16-39 39-39s39 14 39 39"/></svg><div class="frame-corner c1"></div><div class="frame-corner c2"></div><div class="frame-corner c3"></div><div class="frame-corner c4"></div></div><div class="voice-wave"><i v-for="n in 27" :key="n" :style="{height: (8+Math.abs(Math.sin(n*.7))*27)+'px'}"></i></div><div class="voice-caption">让内容拥有自己的声音</div></div><div class="composition-chip"><span>文案</span><i>→</i><span>声音</span><i>→</i><span>视频</span></div></div>
   </section>
   <section class="activity-card" aria-labelledby="activity-title"><div class="card-heading"><h2 id="activity-title">创作记录</h2><button type="button" class="text-button" :disabled="loading" @click="refreshStats" aria-label="刷新任务统计">{{loading?'更新中…':'刷新'}}</button></div><div class="task-metrics"><div v-for="(item,i) in stats" :key="item.label" class="task-metric" :class="{'metric-total':i===0}"><span>{{item.label}}</span><strong>{{loading?'…':item.value??'—'}}</strong><small>{{item.today===null?'暂无可用数据':'今日新增 '+item.today}}</small></div></div><p v-if="unavailable" class="stats-note" role="status">暂时无法读取任务记录，请检查服务后刷新。</p><p v-else class="stats-note">数据来自此设备的创作任务记录</p></section>
  </div>
  <section class="overview-section" aria-labelledby="resources-title"><div class="section-heading"><h2 id="resources-title">创作所需，准备就绪</h2><span>你的素材与表达</span></div><div class="resource-grid"><router-link v-for="tool in tools" :key="tool.tag" :to="tool.path" class="resource-card"><span class="resource-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path :d="tool.icon"/></svg></span><div><h3>{{tool.name}}</h3><p>{{tool.desc}}</p></div><span class="resource-arrow" aria-hidden="true">↗</span></router-link></div></section>
  <section class="overview-section getting-started" aria-labelledby="start-title"><div class="section-heading"><h2 id="start-title">第一次创作</h2><router-link to="/setting">检查创作环境 <span aria-hidden="true">↗</span></router-link></div><div class="start-steps"><router-link v-for="step in steps" :key="step.n" :to="step.path" class="start-step"><span class="step-number">{{step.n}}</span><div><h3>{{step.name}}</h3><p>{{step.text}}</p></div><span aria-hidden="true">→</span></router-link></div></section>
 </div>
